// dsh-theme-wallpaper — client bundle.
// Injects a wallpaper background and semi-transparent panel overrides.
window.__ModuleLoader__.load({
  id: "dsh-theme-wallpaper",
  factory: (require) => {
    var module = { exports: {} };
    var exports = module.exports;

    // Wallpaper as an embedded data URI (self-contained; no host asset route needed).
    var BG = "data:image/jpeg;base64,";

    var css = [
      "html { background: #0f0f14; }",
      "body {",
      "  background-image: url('" + BG + "') !important;",
      "  background-size: cover !important;",
      "  background-position: center !important;",
      "  background-repeat: no-repeat !important;",
      "  background-attachment: fixed !important;",
      "  --dsw-alias-bg-base: rgba(0, 0, 0, 0.20) !important;",
      "  --dsw-alias-bg-layer-1: rgba(255, 255, 255, 0.70) !important;",
      "  --dsw-alias-bg-layer-2: rgba(255, 255, 255, 0.80) !important;",
      "  --dsw-alias-bg-layer-3: rgba(255, 255, 255, 0.88) !important;",
      "  --dsw-specific-sidebar-fill: rgba(246, 246, 247, 0.70) !important;",
      "  --dsw-alias-bg-module-platform: rgba(245, 246, 247, 0.70) !important;",
      "  --dsw-alias-button-elevated-fill: rgba(255, 255, 255, 0.50) !important;",
      "  --dsw-specific-input-major: rgba(255, 255, 255, 0.50) !important;",
      "  --dsw-specific-menu: rgba(255, 255, 255, 0.95) !important;",
      "}",
      "body[data-ds-dark-theme] {",
      "  --dsw-alias-bg-base: rgba(0, 0, 0, 0.20) !important;",
      "  --dsw-alias-bg-layer-1: rgba(20, 21, 24, 0.70) !important;",
      "  --dsw-alias-bg-layer-2: rgba(26, 27, 31, 0.78) !important;",
      "  --dsw-alias-bg-layer-3: rgba(32, 33, 38, 0.86) !important;",
      "  --dsw-specific-sidebar-fill: rgba(30, 32, 38, 0.45) !important;",
      "  --dsw-alias-bg-module-platform: rgba(28, 29, 33, 0.70) !important;",
      "  --dsw-alias-button-elevated-fill: rgba(67, 69, 74, 0.50) !important;",
      "  --dsw-specific-input-major: rgba(44, 44, 46, 0.50) !important;",
      "  --dsw-specific-menu: rgba(26, 27, 31, 0.94) !important;",
      "}"
    ].join("\n");

    var tagId = "dsh-theme-wallpaper/theme.css";
    if (typeof document !== "undefined" && document.querySelector("style[data-plugin-css=" + JSON.stringify(tagId) + "]") === null) {
      var tag = document.createElement("style");
      tag.dataset.plugin = "dsh-theme-wallpaper";
      tag.dataset.pluginCss = tagId;
      tag.textContent = css;
      document.head.appendChild(tag);
    }

    var inject = ["theme"];

    // Client plugin body: force dark theme + inject the wallpaper CSS.
    function apply(ctx) {
      // 通过官方主题服务把偏好切成深色，避免被 ThemePresenter 覆盖。
      if (ctx.theme && typeof ctx.theme.setTheme === "function") {
        ctx.theme.setTheme("dark");
      }
    }
    exports.apply = apply;
    exports.inject = inject;

    return module.exports;
  }
});
